#include <iostream>
#include <string>
using namespace std;

struct Product {
    string name;
    int qty;
    double price;
};

void printAll(const Product list[], int n) {
    for (int i = 0; i < n; i++)
        cout << list[i].name << "  x" << list[i].qty << "  @ " << list[i].price << endl;
}

double totalValue(const Product list[], int n) {
    double t = 0;
    for (int i = 0; i < n; i++)
        t += list[i].qty * list[i].price;
    return t;
}

void restock(Product list[], int n, int amount) {
    for (int i = 0; i < n; i++)
        if (list[i].qty < 5) list[i].qty += amount;
}

int main() {
    Product shop[3] = { {"Pen", 20, 30}, {"Notebook", 3, 150}, {"Ruler", 2, 50} };
    restock(shop, 3, 10);
    printAll(shop, 3);
    cout << "Stock value: Rs. " << totalValue(shop, 3) << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    string name;
    int marks;
};

int readAll(Student list[], int maxSize) {
    int n;
    cin >> n;
    if (n > maxSize) n = maxSize;
    for (int i = 0; i < n; i++) {
        cin >> list[i].name >> list[i].marks;
    }
    return n;
}

void printAll(const Student list[], int n) {
    for (int i = 0; i < n; i++) {
        cout << i + 1 << ". " << list[i].name << " " << list[i].marks << endl;
    }
}

int findByName(const Student list[], int n, string key) {
    for (int i = 0; i < n; i++) {
        if (list[i].name == key) return i;
    }
    return -1;
}

int bestIndex(const Student list[], int n) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (list[i].marks > list[best].marks) best = i;
    }
    return best;
}

int main() {
    Student cls[10];
    int n = 0;
    int choice;
    do {
        cin >> choice;
        switch (choice) {
            case 1:
                n = readAll(cls, 10);
                cout << n << " records read" << endl;
                break;
            case 2:
                printAll(cls, n);
                break;
            case 3: {
                string key;
                cin >> key;
                int idx = findByName(cls, n, key);
                if (idx == -1) cout << key << " not found" << endl;
                else cout << key << " has " << cls[idx].marks << " marks" << endl;
                break;
            }
            case 4: {
                int b = bestIndex(cls, n);
                cout << "Topper: " << cls[b].name << " (" << cls[b].marks << ")" << endl;
                break;
            }
            case 0:
                cout << "Bye" << endl;
                break;
            default:
                cout << "Invalid choice" << endl;
        }
    } while (choice != 0);
    return 0;
}

